"""Step 3 - Vocal lock. The vocal is never regenerated by AI: it is only
time-stretched to the project BPM (pitch unchanged) and, optionally,
pitch-shifted. Uses Rubber Band via Spotify's pedalboard - studio-grade,
formant-preserving, no extra binaries needed on Windows."""

from __future__ import annotations

from dataclasses import dataclass, asdict
from pathlib import Path

import numpy as np
import pedalboard

from .audio_io import load_stereo, save_wav, PROJECT_SR

MIN_RATIO, MAX_RATIO = 0.5, 2.0  # beyond this, vocals smear - refuse rather than ruin it


@dataclass
class LockResult:
    path: str
    source_bpm: float
    target_bpm: float
    stretch_factor: float
    pitch_semitones: float
    duration: float
    phrases: list[dict]

    def to_dict(self) -> dict:
        return asdict(self)


def lock_vocal(src_path: str | Path, out_path: str | Path, source_bpm: float, target_bpm: float,
               pitch_semitones: float = 0.0, phrases: list[dict] | None = None) -> LockResult:
    if source_bpm <= 0 or target_bpm <= 0:
        raise ValueError("BPM must be above 0")
    factor = target_bpm / source_bpm  # >1 = faster/shorter
    if not (MIN_RATIO <= factor <= MAX_RATIO):
        raise ValueError(
            f"{source_bpm:g} -> {target_bpm:g} BPM is a {factor:.2f}x change - too far for a clean "
            "stretch. Try half/double the target BPM.")
    if abs(pitch_semitones) > 12:
        raise ValueError("Pitch shift is limited to +/-12 semitones")

    audio = load_stereo(src_path, PROJECT_SR)
    if abs(factor - 1.0) < 1e-4 and abs(pitch_semitones) < 1e-4:
        out = audio
    else:
        out = pedalboard.time_stretch(
            audio, PROJECT_SR,
            stretch_factor=float(factor),
            pitch_shift_in_semitones=float(pitch_semitones),
            high_quality=True,
            transient_mode="smooth",  # smooth suits sustained vocals
            preserve_formants=True,   # keeps the voice sounding natural when pitched
        )
    out = np.clip(out, -1.0, 1.0).astype(np.float32)
    save_wav(out_path, out)

    scaled = [{**p, "start": round(p["start"] / factor, 4), "end": round(p["end"] / factor, 4)}
              for p in (phrases or [])]
    return LockResult(
        path=str(out_path), source_bpm=source_bpm, target_bpm=target_bpm,
        stretch_factor=round(factor, 5), pitch_semitones=pitch_semitones,
        duration=round(out.shape[-1] / PROJECT_SR, 3), phrases=scaled,
    )
